import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Select","description":"","frontmatter":{},"headers":[],"relativePath":"components/select.md","filePath":"components/select.md"}'),d={name:"components/select.md"};function i(n,e,s,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="select" tabindex="-1">Select <a class="header-anchor" href="#select" aria-label="Permalink to &quot;Select&quot;">​</a></h1><p>Select chooses one value from a list of its own.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for five options or more, or options with a description. Two to four options are a <a href="./segmented">Segmented</a> or a <a href="./radio-group">RadioGroup</a>; a long list, or a phone, calls for a <a href="./native-select">NativeSelect</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>options</code></td><td>required</td><td><code>{ value, label, description? }[]</code></td></tr><tr><td><code>value</code></td><td></td><td>The chosen value (bindable)</td></tr><tr><td><code>placeholder</code></td><td><code>&#39;&#39;</code></td><td>The text while nothing is chosen, faint</td></tr><tr><td><code>ariaLabel</code></td><td></td><td>The accessible name without a Field</td></tr><tr><td><code>id</code></td><td></td><td>The id of the trigger</td></tr><tr><td><code>error</code></td><td><code>false</code></td><td>The line turns red</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>Does not open</td></tr><tr><td><code>onchange</code></td><td></td><td>Called with the chosen value</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The trigger is the control of a button, of the height its container declares, with the chosen label on the left, one line with an ellipsis, and a chevron on the right; its line is blue-ink while the list is open. The list is a popover, so it shows above everything, below the trigger, at least as wide as it and 12rem, and never wider than the window; it opens upward when there is no room below. It has the panel surface and one line in line-strong. Each option is as high as a list item, with pad-md at the sides and a check mark on the left of the chosen one; an option with a description has two lines gap-sm apart and pad-md above and below. The arrow keys, Home and End move between the options, Enter or Space chooses one, and a press outside, Escape or Tab closes the list; Escape returns the focus to the trigger.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/select/" title="Select" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/select/" target="_blank" rel="noopener">Select</a></figcaption></figure>',10)])])}const m=t(d,[["render",i]]);export{f as __pageData,m as default};
